/* GSAP 3 stub — replace with real GSAP 3.12+ for enhanced animations.
   Download: https://gsap.com/community/files/gsap-public/minified/
   Place gsap.min.js and ScrollTrigger.min.js in this lib/ folder.
*/
(function(global){
  "use strict";
  function noop(){}
  var gsap={
    registerPlugin:noop,
    to:function(t,v){return{};},
    from:function(t,v){return{};},
    fromTo:function(t,a,b){return{};},
    set:function(t,v){
      var els=typeof t==="string"?Array.from(document.querySelectorAll(t)):[t].flat();
      els.forEach(function(el){if(!el)return;
        if(v.opacity!==undefined)el.style.opacity=v.opacity;
        if(v.y!==undefined)el.style.transform="translateY("+v.y+"px)";
        if(v.x!==undefined)el.style.transform="translateX("+v.x+"px)";
      });
    },
    timeline:function(o){return{to:noop,from:noop,fromTo:noop,add:noop,play:noop,pause:noop,kill:noop};},
    killTweensOf:noop,
    utils:{toArray:function(s){return typeof s==="string"?Array.from(document.querySelectorAll(s)):[].concat(s||[]);}},
    ticker:{add:noop,remove:noop},
    context:function(fn){fn&&fn();return{revert:noop};}
  };
  global.gsap=gsap;
})(window);
